// Modo do node: "Run Once for Each Item"

const raw = $json.output[0].content[0].text;

const carrossel = typeof raw === 'string'
  ? JSON.parse(raw.replace(/```json\s*|```/g, '').trim())
  : raw;

// trava de segurança: garante que bullets sempre existe como array,
// mesmo se o modelo esquecer de incluir o campo em algum slide
carrossel.slides = carrossel.slides.map(slide => ({
  ...slide,
  bullets: Array.isArray(slide.bullets) ? slide.bullets : []
}));

return { json: carrossel };

// ============================================================
// Node: "Montar HTML do Slide" (Versão Redesenhada - Centralizada)
// ============================================================

// ============================================================
// CONFIGURAÇÕES
// ============================================================

const LOGO_URL =
  'https://YOUR_SUPABASE_ID.supabase.co/storage/v1/object/public/agildev-assets/agildev-logo-transparent.png';

const MASCOTE_URL =
  'https://YOUR_SUPABASE_ID.supabase.co/storage/v1/object/public/agildev-assets/agildev-mascote-transparent.png';

const TAG_POR_TIPO = {
  problema: 'O PROBLEMA',
  solucao: 'A SOLUÇÃO',
  consequencia: 'O IMPACTO'
};

const TOTAL_SLIDES = 5;

// ============================================================
// DADOS DO SLIDE
// ============================================================

const item = $input.item.json;

const numero = Number(item.numero);
const tipo = typeof item.tipo === 'string' ? item.tipo.trim() : '';
const titulo = typeof item.titulo === 'string' ? item.titulo.trim() : '';

let subtitulo = typeof item.subtitulo === 'string' ? item.subtitulo.trim() : '';

let bullets = Array.isArray(item.bullets)
  ? item.bullets
      .filter((b) => typeof b === 'string')
      .map((b) => b.trim())
      .filter(Boolean)
  : [];

const precisaImagem = item.precisa_imagem === true;
const imagemBase64 = typeof item.imagem_base64 === 'string' ? item.imagem_base64.trim() : '';

const activeIndex = numero - 1;

// ============================================================
// VALIDAÇÕES BÁSICAS E FALLBACKS
// ============================================================

if (!Number.isInteger(numero) || numero < 1 || numero > TOTAL_SLIDES) {
  throw new Error(`Número de slide inválido: "${item.numero}".`);
}

if (!tipo) {
  throw new Error(`Slide ${numero}: tipo não informado.`);
}

if (!titulo) {
  throw new Error(`Slide ${numero}: título vazio.`);
}

const TIPOS_VALIDOS = ['hook', 'problema', 'consequencia', 'solucao', 'cta'];

if (!TIPOS_VALIDOS.includes(tipo)) {
  throw new Error(`Slide ${numero}: tipo inválido "${tipo}".`);
}

// 1. Tratamento para HOOK e CTA
if (tipo === 'hook' || tipo === 'cta') {
  bullets = [];
  if (!subtitulo) {
    subtitulo = 'Entenda como otimizar os processos e a eficiência operacional da sua empresa com inteligência artificial.';
  }
}

// 2. Tratamento para Slides de Conteúdo
if (tipo === 'problema' || tipo === 'consequencia' || tipo === 'solucao') {
  if (bullets.length > 0) {
    subtitulo = ''; 
  } else if (subtitulo) {
    bullets = []; 
  } else {
    bullets = [
      'Análise detalhada dos gargalos do fluxo operacional.',
      'Aplicação de otimizações para aumento de produtividade.'
    ];
  }
}

if (precisaImagem && !imagemBase64) {
  throw new Error(`Slide ${numero}: precisa_imagem=true, mas imagem_base64 está vazia.`);
}

// ============================================================
// HELPERS DE LAYOUT
// ============================================================

function countChars(text) {
  return [...(text || '')].length;
}

function getTituloSize(tipo, titulo) {
  const length = countChars(String(titulo || '').replace(/\*\*/g, ''));

  if (tipo === 'hook') {
    if (length > 50) return 72;
    if (length > 35) return 82;
    return 92;
  }

  if (tipo === 'problema' || tipo === 'solucao') {
    if (length > 48) return 48;
    if (length > 38) return 52;
    return 58;
  }

  if (length > 58) return 50;
  if (length > 46) return 56;
  return 62;
}

function getTituloLineHeight(tipo, fontSize) {
  if (tipo === 'hook') return 1.02;
  if (fontSize <= 48) return 1.10;
  return 1.12;
}

function getBulletSize(bullets) {
  const count = Array.isArray(bullets) ? bullets.length : 0;

  if (count >= 4) return 26;
  if (count === 3) return 28;
  return 32;
}

function getBulletSpacing(bullets) {
  const count = Array.isArray(bullets) ? bullets.length : 0;

  if (count >= 4) return 16;
  if (count === 3) return 20;
  return 24;
}

function getContentWidth(hasImage) {
  return hasImage ? '60%' : '100%';
}

function getBackgroundPosition(index) {
  const positions = ['0% 0%', '25% 0%', '50% 0%', '75% 0%', '100% 0%'];
  return positions[index] || '50% 0%';
}

function getProgressPercent(numero) {
  return Math.min(100, Math.max(20, (numero / TOTAL_SLIDES) * 100));
}

// ============================================================
// ESCAPE HTML E GLOW
// ============================================================

function escapeHtml(value) {
  if (value === null || value === undefined) return '';

  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function applyGlow(text) {
  if (!text) return '';

  let safeText = escapeHtml(text);
  safeText = safeText.replace(/\*\*(.+?)\*\*/g, '<span class="glow">$1</span>');

  return safeText;
}

// ============================================================
// RENDERS
// ============================================================

function renderBullets(bullets, fontSize, spacing) {
  if (!Array.isArray(bullets) || bullets.length === 0) return '';

  const items = bullets
    .map((bullet) => {
      let safeBullet = escapeHtml(bullet);
      safeBullet = safeBullet.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');

      return `
        <li style="font-size:${fontSize}px; margin-bottom:${spacing}px;">
          ${safeBullet}
        </li>
      `;
    })
    .join('');

  return `
    <ul class="bullets">
      ${items}
    </ul>
  `;
}

function progressBar(progressPercent) {
  return `
    <div class="progress-bar-container">
      <div class="progress-bar-fill" style="width:${progressPercent}%"></div>
    </div>
  `;
}

function topbar(tipo) {
  return `
    <div class="topbar">
      <div>
        <img class="logo-img" src="${LOGO_URL}" alt="AgilDev">
      </div>
      ${tipo === 'hook' ? '<div class="year-badge">2026</div>' : ''}
    </div>
  `;
}

function bottombar(currentSlide, tipo) {
  if (tipo === 'hook') {
    return `
      <div class="bottombar hook-bottom">
        <div class="action-item">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/></svg>
          <span>Compartilhe</span>
        </div>
        <div class="action-item">
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/></svg>
          <span>Salve</span>
        </div>
      </div>
    `;
  }

  return `
    <div class="bottombar">
      <div class="slide-counter">
        SLIDE ${currentSlide} / ${TOTAL_SLIDES}
      </div>
    </div>
  `;
}

function circuit(corner) {
  return `
    <div class="circuit circuit-${corner}">
      <svg width="150" height="150" viewBox="0 0 150 150" fill="none" xmlns="http://www.w3.org/2000/svg">
        <path d="M15 135 L15 55 L60 55 L60 15 L135 15" stroke="rgba(255,255,255,0.25)" stroke-width="2" fill="none"/>
        <circle cx="15" cy="135" r="5" fill="rgba(47,216,245,0.7)"/>
        <circle cx="60" cy="55" r="3.5" fill="rgba(255,255,255,0.4)"/>
        <circle cx="135" cy="15" r="5" fill="rgba(47,216,245,0.7)"/>
      </svg>
    </div>
  `;
}

function tag(tipo) {
  const label = TAG_POR_TIPO[tipo];
  if (!label) return '';

  return `
    <div class="tag">
      ${label}
    </div>
  `;
}

// ============================================================
// CONFIGURAÇÕES DINÂMICAS
// ============================================================

const hasImg = precisaImagem && imagemBase64.length > 0;
const tituloSize = getTituloSize(tipo, titulo);
const tituloLineHeight = getTituloLineHeight(tipo, tituloSize);
const bulletSize = getBulletSize(bullets);
const bulletSpacing = getBulletSpacing(bullets);
const contentWidth = getContentWidth(hasImg);
const bgPosition = getBackgroundPosition(activeIndex);
const progressPercent = getProgressPercent(numero);

const tituloHtml = applyGlow(titulo);
const subtituloHtml = escapeHtml(subtitulo);
const bulletsHtml = renderBullets(bullets, bulletSize, bulletSpacing);

const conteudoApoioHtml =
  bullets.length > 0
    ? bulletsHtml
    : `
        <div class="subtitulo">
          ${subtituloHtml}
        </div>
      `;

// ============================================================
// CSS
// ============================================================

const css = `
  @import url('https://fonts.googleapis.com/css2?family=Oswald:wght@600;700&family=Inter:wght@400;500;700;800&display=swap');

  :root {
    --navy-deep: #030712;
    --navy-base: #071328;
    --navy-mid: #0D2248;
    --cyan-glow: #00E5FF;
    --cyan-soft: #7FE3F7;
    --white: #FFFFFF;
    --white-dim: #D1E0ED;
  }

  * {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
  }

  .slide {
    width: 1080px;
    height: 1350px;
    position: relative;
    background: radial-gradient(
      circle at top center,
      var(--navy-mid) 0%,
      var(--navy-base) 55%,
      var(--navy-deep) 100%
    );
    background-size: 100% 100%;
    overflow: hidden;
    color: var(--white);
    font-family: 'Inter', Arial, sans-serif;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
  }

  .progress-bar-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 8px;
    background: rgba(255,255,255,0.08);
    z-index: 100;
  }

  .progress-bar-fill {
    height: 100%;
    background: linear-gradient(90deg, var(--cyan-soft), var(--cyan-glow));
    box-shadow: 0 0 15px var(--cyan-glow);
  }

  .circuit {
    position: absolute;
    z-index: 1;
    opacity: 0.6;
  }

  .circuit-tl { top: 40px; left: 40px; }
  .circuit-br { bottom: 40px; right: 40px; transform: rotate(180deg); }

  .topbar {
    position: absolute;
    top: 55px;
    left: 64px;
    right: 64px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    z-index: 50;
  }

  .logo-img {
    height: 180px;
    width: auto;
    display: block;
  }

  .year-badge {
    border: 2px solid rgba(255,255,255,0.7);
    padding: 8px 28px;
    border-radius: 40px;
    font-size: 22px;
    font-weight: 700;
    color: var(--white);
    letter-spacing: 1px;
  }

  /* POSICIONAMENTO CENTRALIZADO VERTICALMENTE */
  .content {
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: center;
    width: ${contentWidth};
    padding: 0 72px;
    z-index: 10;
  }

  .content-card {
    background: rgba(10, 26, 51, 0.45);
    border: 1.5px solid rgba(47, 216, 245, 0.25);
    border-radius: 24px;
    padding: 48px;
    backdrop-filter: blur(12px);
    width: 100%;
    box-shadow: 0 20px 50px rgba(0,0,0,0.4);
  }

  .tag {
    display: inline-block;
    background: var(--cyan-glow);
    color: var(--navy-deep);
    font-size: 22px;
    font-weight: 800;
    letter-spacing: 1.5px;
    text-transform: uppercase;
    padding: 8px 22px;
    border-radius: 8px;
    margin-bottom: 24px;
  }

  .titulo {
    font-family: 'Inter', sans-serif;
    font-size: ${tituloSize}px;
    font-weight: 800;
    line-height: ${tituloLineHeight};
    letter-spacing: -1px;
    text-transform: uppercase;
    margin-bottom: 28px;
    word-break: normal;
    overflow-wrap: break-word;
  }

  /* ESTILO ESPECIAL DA CAPA (HOOK) */
  .slide-hook .content-card {
    background: transparent;
    border: none;
    padding: 0;
    box-shadow: none;
    backdrop-filter: none;
  }

  .slide-hook .titulo {
    font-family: 'Oswald', sans-serif;
    font-weight: 700;
    line-height: 1.05;
    letter-spacing: 0px;
    color: var(--white);
    text-shadow: 0 10px 30px rgba(0,0,0,0.5);
  }

  .titulo .glow {
    color: var(--cyan-glow);
    text-shadow: 0 0 25px rgba(0, 229, 255, 0.8), 0 0 50px rgba(0, 229, 255, 0.4);
  }

  .subtitulo {
    font-size: 32px;
    font-weight: 400;
    line-height: 1.5;
    color: var(--white-dim);
    max-width: 100%;
    overflow-wrap: break-word;
  }

  .slide-hook .subtitulo {
    font-size: 34px;
    color: var(--white-dim);
    margin-top: 10px;
  }

  .bullets {
    list-style: none;
    margin-top: 10px;
    width: 100%;
  }

  .bullets li {
    line-height: 1.4;
    color: var(--white-dim);
    padding-left: 36px;
    position: relative;
    overflow-wrap: break-word;
  }

  .bullets li::before {
    content: '●';
    position: absolute;
    left: 0;
    top: 0px;
    color: var(--cyan-glow);
    font-size: 22px;
  }

  .bullets li strong {
    color: var(--white);
    font-weight: 700;
  }

  .swipe-pill {
    display: inline-flex;
    align-items: center;
    gap: 14px;
    border: 2px solid rgba(255,255,255,0.8);
    border-radius: 40px;
    padding: 14px 32px;
    margin-top: 40px;
    width: fit-content;
    background: rgba(0,0,0,0.2);
  }

  .swipe-pill .txt {
    font-size: 24px;
    font-weight: 600;
    color: var(--white);
  }

  .bottombar {
    position: absolute;
    bottom: 50px;
    left: 64px;
    right: 64px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    z-index: 50;
  }

  .hook-bottom {
    justify-content: space-between;
    border-top: 1px solid rgba(255,255,255,0.15);
    padding-top: 25px;
  }

  .action-item {
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--white);
    font-size: 22px;
    font-weight: 500;
  }

  .slide-counter {
    font-size: 20px;
    color: var(--cyan-soft);
    font-weight: 700;
    letter-spacing: 1.5px;
  }

  /* IMAGENS E MASCOTE */
  .img-slot {
    position: absolute;
    right: 0;
    top: 0;
    bottom: 0;
    width: 42%;
    z-index: 2;
    overflow: hidden;
  }

  .img-slot img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }

  .img-slot::after {
    content: '';
    position: absolute;
    inset: 0;
    background: linear-gradient(
      to right,
      var(--navy-deep) 0%,
      rgba(3,7,18,0.5) 40%,
      transparent 100%
    );
  }

  /* CENTRALIZAÇÃO DO SLIDE DE CTA (SLIDE 5) */
  .slide-cta {
    justify-content: center;
    align-items: center;
  }

  .slide-cta .content {
    width: 100%;
    align-items: center;
    margin-top: -60px;
  }

  .slide-cta .content-card {
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
  }

  .slide-cta .mascot-slot {
    position: absolute;
    bottom: 90px;
    left: 50%;
    transform: translateX(-50%);
    width: 260px;
    z-index: 20;
    filter: drop-shadow(0 20px 30px rgba(0,0,0,0.7));
  }

  .slide-cta .mascot-slot img {
    width: 100%;
    height: auto;
    display: block;
  }

  .cta-box {
    margin-top: 32px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 16px;
    background: var(--cyan-glow);
    padding: 22px 42px;
    border-radius: 14px;
    width: fit-content;
    box-shadow: 0 10px 30px rgba(0, 229, 255, 0.4);
  }

  .cta-box .cta-text {
    font-size: 28px;
    font-weight: 800;
    color: var(--navy-deep);
  }
`;

// ============================================================
// HTML FINAL
// ============================================================

let html = '';

if (tipo === 'hook') {
  html = `
    <div class="slide slide-hook">
      ${progressBar(progressPercent)}
      ${topbar(tipo)}
      <div class="content">
        <div class="content-card">
          <div class="titulo">${tituloHtml}</div>
          <div class="subtitulo">${subtituloHtml}</div>
          <div class="swipe-pill">
            <div class="txt">deslize para aprender »»</div>
          </div>
        </div>
      </div>
      ${bottombar(numero, tipo)}
    </div>
  `;
} else if (tipo === 'problema' || tipo === 'solucao') {
  html = `
    <div class="slide">
      ${progressBar(progressPercent)}
      ${circuit('tl')}
      ${!hasImg ? circuit('br') : ''}
      ${topbar(tipo)}
      <div class="content">
        <div class="content-card">
          ${tag(tipo)}
          <div class="titulo">${tituloHtml}</div>
          ${conteudoApoioHtml}
        </div>
      </div>
      ${
        hasImg
          ? `<div class="img-slot"><img src="${escapeHtml(imagemBase64)}" alt=""></div>`
          : ''
      }
      ${bottombar(numero, tipo)}
    </div>
  `;
} else if (tipo === 'consequencia') {
  html = `
    <div class="slide">
      ${progressBar(progressPercent)}
      ${circuit('tl')}
      ${circuit('br')}
      ${topbar(tipo)}
      <div class="content">
        <div class="content-card">
          ${tag(tipo)}
          <div class="titulo">${tituloHtml}</div>
          ${conteudoApoioHtml}
        </div>
      </div>
      ${bottombar(numero, tipo)}
    </div>
  `;
} else if (tipo === 'cta') {
  html = `
    <div class="slide slide-cta">
      ${progressBar(progressPercent)}
      ${circuit('tl')}
      ${topbar(tipo)}
      <div class="content">
        <div class="content-card">
          <div class="titulo">${tituloHtml}</div>
          <div class="subtitulo">${subtituloHtml}</div>
          <div class="cta-box">
            <div class="cta-text">Fale com a AgilDev →</div>
          </div>
        </div>
      </div>
      <div class="mascot-slot">
        <img src="${MASCOTE_URL}" alt="Mascote AgilDev">
      </div>
      ${bottombar(numero, tipo)}
    </div>
  `;
} else {
  throw new Error(`Tipo de slide desconhecido: "${tipo}"`);
}

// ============================================================
// RETORNO
// ============================================================

return {
  json: {
    html,
    css,
    numero
  }
};

