const imagem = $json.data?.[0]?.b64_json;

if (!imagem) {
  throw new Error('A OpenAI não retornou b64_json.');
}

return {
  json: {
    numero: $('Split Slides').item.json.numero,
    tipo: $('Split Slides').item.json.tipo,
    titulo: $('Split Slides').item.json.titulo,
    subtitulo: $('Split Slides').item.json.subtitulo,
    precisa_imagem: $('Split Slides').item.json.precisa_imagem,
    prompt_imagem: $('Split Slides').item.json.prompt_imagem,
    imagem_base64: `data:image/png;base64,${imagem}`
  }
};

const temasRecentes = $input.all()
  .map(item => item.json.tema)
  .filter(tema => typeof tema === 'string' && tema.trim() !== '')
  .map(tema => tema.trim());

return [
  {
    json: {
      temas_recentes: temasRecentes
    }
  }
];

const items = $input.all();

if (items.length === 0) {
  throw new Error('GPT Estrategista não retornou nenhum item.');
}

if (items.length > 1) {
  throw new Error(
    `GPT Estrategista retornou ${items.length} itens. Esperado: 1.`
  );
}

const item = items[0].json;

// O node OpenAI pode devolver o texto em diferentes estruturas.
// Tentamos primeiro a estrutura usada pelo seu fluxo atual.
let tema = '';

if (
  item.output &&
  Array.isArray(item.output) &&
  item.output[0]?.content &&
  Array.isArray(item.output[0].content)
) {
  const content = item.output[0].content;

  const outputText = content.find(
    c => c.type === 'output_text'
  );

  if (outputText?.text) {
    tema = outputText.text;
  }
}

// Fallback caso o node já tenha colocado o texto diretamente.
if (!tema && typeof item.text === 'string') {
  tema = item.text;
}

if (!tema && typeof item.output_text === 'string') {
  tema = item.output_text;
}

tema = String(tema || '')
  .trim()
  .replace(/^["']|["']$/g, '')
  .replace(/\s+/g, ' ');

if (!tema) {
  throw new Error(
    'GPT Estrategista não retornou um tema válido.'
  );
}

return [
  {
    json: {
      tema
    }
  }
];
